grid = [[0]*28 for _ in range(28)]

for r in range(28):
    for c in range(28):
        if c in wall_cols or r in wall_rows:
            grid[r][c] = 8
        else:
            sec, local_r = get_section_and_local(r)
            if local_r == 1 and sec in sections_producing_markers:
                if c in section_marker_cols[sec]:
                    grid[r][c] = 3 if c == 12 else 2

# Verify test points
test_points = [(1,12), (6,2), (6,22), (16,2), (21,12)]
expected = [3, 2, 2, 2, 3]
print("Test points verification:")
all_pass = True
for (r,c), exp in zip(test_points, expected):
    val = grid[r][c]
    pass_test = val == exp
    print(f"  ({r},{c}): {val} vs {exp} {'✓' if pass_test else '✗'}")
    if not pass_test:
        all_pass = False

print(f"\nAll pass: {all_pass}")

submission = {"action": "submit", "grid": grid}
print("\nSubmitting...")
print(json.dumps(submission))
